/**
 * Compile-time check that the hand-written types in ./index.ts use the same field names as the
 * Rust types they mirror (generated by ts-rs into ./generated). `tsc` fails with the offending
 * field names when a field is added, removed or renamed on either side.
 *
 * Field *types* may deliberately be narrower in the frontend (e.g. `'local' | 'cloud'` instead of
 * `string`), so only names are compared. Intentional differences are listed per type.
 */
import type * as Frontend from './index';

import type { LlamaServerConfig as RustLlamaServerConfig } from './generated/LlamaServerConfig';
import type { ChatMessage as RustChatMessage } from './generated/ChatMessage';
