import type { AppSettings as RustAppSettings } from './generated/AppSettings';
import type { ScannedLive2d as RustScannedLive2d } from './generated/ScannedLive2d';
import type { EmotionResult as RustEmotionResult } from './generated/EmotionResult';
import type { UserPersona as RustUserPersona } from './generated/UserPersona';
import type { SwipeVariant as RustSwipeVariant } from './generated/SwipeVariant';
import type { StoredChatMessage as RustStoredChatMessage } from './generated/StoredChatMessage';
import type { LlmPreset as RustLlmPreset } from './generated/LlmPreset';
import type { HfModelSummary as RustHfModelSummary } from './generated/HfModelSummary';
