import type { UpdateInfo as RustUpdateInfo } from './generated/UpdateInfo';

/** `true` when both types have the same keys apart from the listed exceptions, else the difference. */
type SameFields<F, R, OnlyFrontend extends PropertyKey = never, OnlyRust extends PropertyKey = never> = [
  Exclude<keyof F, keyof R | OnlyFrontend>,
  Exclude<keyof R, keyof F | OnlyRust>,
] extends [never, never]
  ? true
  : { onlyInFrontend: Exclude<keyof F, keyof R | OnlyFrontend>; onlyInRust: Exclude<keyof R, keyof F | OnlyRust> };

const expectMatch = <T extends true>(): T | undefined => undefined;

expectMatch<SameFields<Frontend.LlamaServerConfig, RustLlamaServerConfig>>();
// thought is shown in the UI but not sent to the model.
expectMatch<SameFields<Frontend.ChatMessage, RustChatMessage, 'thought', never>>();
expectMatch<SameFields<Frontend.SamplingParams, RustSamplingParams>>();
expectMatch<SameFields<Frontend.ChatRequest, RustChatRequest>>();
expectMatch<SameFields<Frontend.CharacterData, RustCharacterData>>();
expectMatch<SameFields<Frontend.CharacterCardV2, RustCharacterCardV2>>();
expectMatch<SameFields<Frontend.CharacterProfile, RustCharacterProfile>>();
expectMatch<SameFields<Frontend.LorebookEntry, RustLorebookEntry>>();
expectMatch<SameFields<Frontend.Lorebook, RustLorebook>>();
expectMatch<SameFields<Frontend.EvaluatedLoreResult, RustEvaluatedLoreResult>>();
expectMatch<SameFields<Frontend.StateVariable, RustStateVariable>>();
expectMatch<SameFields<Frontend.PsychologyState, RustPsychologyState>>();
expectMatch<SameFields<Frontend.RelationshipState, RustRelationshipState>>();
expectMatch<SameFields<Frontend.SoulMemoryPipelineRequest, RustSoulMemoryPipelineRequest>>();
expectMatch<SameFields<Frontend.SoulMemoryPipelineResult, RustSoulMemoryPipelineResult>>();
expectMatch<SameFields<Frontend.CognitiveOverview, RustCognitiveOverview>>();
expectMatch<SameFields<Frontend.PromptContext, RustPromptContext>>();
expectMatch<SameFields<Frontend.DiceRollResult, RustDiceRollResult>>();
expectMatch<SameFields<Frontend.Combatant, RustCombatant>>();
expectMatch<SameFields<Frontend.EncounterState, RustEncounterState>>();
expectMatch<SameFields<Frontend.ScenePreview, RustScenePreview>>();
expectMatch<SameFields<Frontend.SceneDefinition, RustSceneDefinition>>();
expectMatch<SameFields<Frontend.InventoryItem, RustInventoryItem>>();
expectMatch<SameFields<Frontend.TaggedChoice, RustTaggedChoice>>();
// ts-rs puts the event tag on the StageEventCard union instead.
expectMatch<SameFields<Frontend.DiceEventData, RustDiceEventData, 'type', never>>();
// ts-rs puts the event tag on the StageEventCard union instead.
expectMatch<SameFields<Frontend.ClockUpdateData, RustClockUpdateData, 'type', never>>();
// ts-rs puts the event tag on the StageEventCard union instead.
expectMatch<SameFields<Frontend.RestEventData, RustRestEventData, 'type', never>>();
expectMatch<SameFields<Frontend.SceneTurnMessage, RustSceneTurnMessage>>();
expectMatch<SameFields<Frontend.SceneState, RustSceneState>>();
expectMatch<SameFields<Frontend.StageTurnRequest, RustStageTurnRequest>>();
expectMatch<SameFields<Frontend.Goal, RustGoal>>();
expectMatch<SameFields<Frontend.ToolCallRequest, RustToolCallRequest>>();
expectMatch<SameFields<Frontend.CompanionSettings, RustCompanionSettings>>();
expectMatch<SameFields<Frontend.CompanionState, RustCompanionState>>();
expectMatch<SameFields<Frontend.EnvironmentSnapshot, RustEnvironmentSnapshot>>();
expectMatch<SameFields<Frontend.McpServerConfig, RustMcpServerConfig>>();
expectMatch<SameFields<Frontend.McpToolInfo, RustMcpToolInfo>>();
expectMatch<SameFields<Frontend.CompanionPlugin, RustCompanionPlugin>>();
expectMatch<SameFields<Frontend.ScannedModel, RustScannedModel>>();
// hidden_character_ids is managed by the backend only.
expectMatch<SameFields<Frontend.AppSettings, RustAppSettings, never, 'hidden_character_ids'>>();
expectMatch<SameFields<Frontend.ScannedLive2d, RustScannedLive2d>>();
expectMatch<SameFields<Frontend.EmotionResult, RustEmotionResult>>();
expectMatch<SameFields<Frontend.UserPersona, RustUserPersona>>();
expectMatch<SameFields<Frontend.SwipeVariant, RustSwipeVariant>>();
expectMatch<SameFields<Frontend.StoredChatMessage, RustStoredChatMessage>>();
expectMatch<SameFields<Frontend.LlmPreset, RustLlmPreset>>();
expectMatch<SameFields<Frontend.HfModelSummary, RustHfModelSummary>>();
expectMatch<SameFields<Frontend.HfGgufFile, RustHfGgufFile>>();
expectMatch<SameFields<Frontend.DownloadProgressEvent, RustDownloadProgressEvent>>();
expectMatch<SameFields<Frontend.ChubSearchItem, RustChubSearchItem>>();
expectMatch<SameFields<Frontend.ChubSearchResult, RustChubSearchResult>>();
expectMatch<SameFields<Frontend.CharacterImportResult, RustCharacterImportResult>>();
expectMatch<SameFields<Frontend.BackupManifest, RustBackupManifest>>();
expectMatch<SameFields<Frontend.BackupEntryInfo, RustBackupEntryInfo>>();
expectMatch<SameFields<Frontend.ImageGenConfig, RustImageGenConfig>>();
expectMatch<SameFields<Frontend.DiscordRpcActivity, RustDiscordRpcActivity>>();
expectMatch<SameFields<Frontend.DiscordBotStatus, RustDiscordBotStatus>>();
expectMatch<SameFields<Frontend.CharacterWizardInput, RustCharacterWizardInput>>();
expectMatch<SameFields<Frontend.UpdateInfo, RustUpdateInfo>>();

expectMatch<SameFields<Frontend.StageNpcPromotion, import('./generated/StageNpcPromotion').StageNpcPromotion>>();
